747	func toTaskSummary(t database2.WorkspaceTask) domain.TaskSummary {
748		isBlocked := t.Status != nil && *t.Status == "blocked"
749		return domain.TaskSummary{
750			ID:            database2.UUIDString(t.ID),
751			TaskID:        database2.UUIDString(t.TaskID),
752			TaskName:      t.TaskName,
753			FeatureID:     database2.UUIDString(t.FeatureID),
754			FeatureName:   t.FeatureName,
755			Title:         t.Title,
756			Status:        derefStr(t.Status),
757			Repo:          derefStr(t.Repo),
758			Branch:        derefStr(t.Branch),
759			IsBlocked:     isBlocked,
760			BlockedReason: derefStr(t.BlockedReason),
761			Pr:            rawJSONOrNil(t.Pr),
762			WorkspacePr:   rawJSONOrNil(t.WorkspacePr),
