766	func toActivityEvent(a database2.WorkspaceActivityEvent) domain.ActivityEvent {
767		e := domain.ActivityEvent{
768			Action:    derefStr(a.Action),
769			Scope:     a.ScopeType,
770			Actor:     derefStr(a.Actor),
771			Note:      derefStr(a.Note),
772			FeatureID: database2.UUIDString(a.FeatureID),
773			TaskID:    database2.UUIDString(a.TaskID),
774		}
775		if a.OccurredAt != nil {
776			if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
777				e.OccurredAt = t
778			}
779		}
780		return e
781	}
