784		switch sort {
785		case "title_asc", "title_desc", "status_asc", "status_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
786			return true
787		default:
788			return false
789		}
790	}
