792	func isValidTaskSearchSort(sort string) bool {
793		switch sort {
794		case "task_id_asc", "task_id_desc", "title_asc", "title_desc", "status_asc", "status_desc", "repo_asc", "repo_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
795			return true
