809	func taskCountsFromRows(rows []database2.WorkspaceFeatureTaskCounts) map[string]domain.TaskCounts {
810		counts := make(map[string]domain.TaskCounts, len(rows))
811		for _, row := range rows {
812			counts[database2.UUIDString(row.FeatureID)] = domain.TaskCounts{
813				Total:      int(row.Total),
814				Done:       int(row.Done),
815				InProgress: int(row.InProgress),
816				Blocked:    int(row.Blocked),
817				Ready:      int(row.Ready),
818				Todo:       int(row.Todo),
819			}
820		}
821		return counts
822	}
823	
824	func countTasksByFeature(tasks []database2.WorkspaceTask) map[string]domain.TaskCounts {
825		counts := make(map[string]domain.TaskCounts, len(tasks))
826		for _, t := range tasks {
827			featureID := database2.UUIDString(t.FeatureID)
828			current := counts[featureID]
829			current.Total++
830			if t.Status != nil {
831				switch *t.Status {
832				case "done":
833					current.Done++
834				case "in_progress":
835					current.InProgress++
836				case "blocked":
837					current.Blocked++
838				case "ready":
839					current.Ready++
840				case "todo":
841					current.Todo++
842				}
843			}
844			counts[featureID] = current
845		}
846		return counts
847	}
848	
849	func countTasks(tasks []database2.WorkspaceTask) domain.TaskCounts {
850		var counts domain.TaskCounts
851		for _, t := range tasks {
852			counts.Total++
853			if t.Status != nil {
854				switch *t.Status {
855				case "done":
856					counts.Done++
857				case "in_progress":
858					counts.InProgress++
859				case "blocked":
860					counts.Blocked++
861				case "ready":
862					counts.Ready++
863				case "todo":
864					counts.Todo++
865				}
866			}
867		}
868		return counts
869	}
870	
871	func parsePRRefs(prData, workspacePRData []byte, repo string) []domain.PullRequestRef {
872		var refs []domain.PullRequestRef
873	
874		var pr map[string]interface{}
875		if prData != nil {
876			if json.Unmarshal(prData, &pr) == nil {
877				if url, ok := pr["url"].(string); ok && url != "" {
878					status, _ := pr["status"].(string)
879					refs = append(refs, domain.PullRequestRef{
880						Label:  "Implementation PR",
881						URL:    url,
882						Status: status,
883						Repo:   repo,
884					})
885				}
886			}
887		}
888	
889		var wsPR map[string]interface{}
890		if workspacePRData != nil {
891			if json.Unmarshal(workspacePRData, &wsPR) == nil {
892				if url, ok := wsPR["url"].(string); ok && url != "" {
893					status, _ := wsPR["status"].(string)
894					refs = append(refs, domain.PullRequestRef{
895						Label:  "Workspace PR",
896						URL:    url,
897						Status: status,
898						Repo:   "management-repo",
899					})
900				}
901			}
902		}
903		return refs
904	}
905	
906	func derefStr(s *string) string {
907		if s == nil {
908			return ""
909		}
910		return *s
911	}
912	
913	func rawJSONOrNil(raw json.RawMessage) json.RawMessage {
914		if len(raw) == 0 || string(raw) == "null" || !json.Valid(raw) {
915			return nil
916		}
917		return raw
918	}
