package service_test

import (
	"context"
	"errors"
	"sort"
	"strconv"
	"strings"
	"testing"
	"time"

	"github.com/tiendv89/workflow-backend/internal/adapter"
	"github.com/tiendv89/workflow-backend/internal/authmw"
	"github.com/tiendv89/workflow-backend/internal/database"
	"github.com/tiendv89/workflow-backend/internal/domain"
	"github.com/tiendv89/workflow-backend/internal/service"
)

// --- fakes ---

type fakeDB struct {
	workspaces  []database.Workspace
	syncRuns    []database.WorkspaceSyncRun
	features    []database.WorkspaceFeature
	documents   []database.WorkspaceFeatureDocument
	tasks       []database.WorkspaceTask
	activity    []database.WorkspaceActivityEvent
	githubSrcs  map[string]database.WorkspaceGitHubSource
	listWSErr   error
	listRunsErr error
	listSrcsErr error
	getWSErr    error
	getRunErr   error

	listWorkspaceTasksCalls   int
	searchWorkspaceTasksCalls int
	getWorkspaceTaskCalls     int
	getWorkspaceTaskByIDCalls int
}

func (f *fakeDB) ListWorkspaces(ctx context.Context) ([]database.Workspace, error) {
	if f.listWSErr != nil {
		return nil, f.listWSErr
	}
	ac, hasAuth := authmw.FromContext(ctx)
	if !hasAuth {
		return f.workspaces, nil
	}
	if len(ac.AccessibleWorkspaceIDs) == 0 {
		return []database.Workspace{}, nil
	}
	allowed := make(map[string]struct{}, len(ac.AccessibleWorkspaceIDs))
	for _, id := range ac.AccessibleWorkspaceIDs {
		allowed[id] = struct{}{}
	}
	out := make([]database.Workspace, 0, len(f.workspaces))
	for _, w := range f.workspaces {
		if _, ok := allowed[database.UUIDString(w.ID)]; ok {
			out = append(out, w)
		}
	}
	return out, nil
}

func (f *fakeDB) GetWorkspace(ctx context.Context, workspaceID string) (database.Workspace, error) {
	if f.getWSErr != nil {
		return database.Workspace{}, f.getWSErr
	}
	ac, hasAuth := authmw.FromContext(ctx)
	if hasAuth {
		accessible := false
